func BindEventServiceSubscribe(service v1.EventServiceHTTPServer) transport.Binding {
	return transport.Binding{
		Operation: v1.OperationEventServiceSubscribe,
		Stream:    true,
		Handler: func(ctx context.Context, c *app.RequestContext) {
			in := new(v1.EventSubscriptionRequest)
			if err := transport.BindRequest(c, in, ""); err != nil {
				transport.FailRequest(c, err)
				return
			}
			if err := transport.ValidateRequest(in); err != nil {
				transport.FailRequest(c, err)
				return
			}
			started := false
			err := service.Subscribe(ctx, in, func(frame *v1.EventFrame) error { return transport.WriteEvent(c, frame, &started) })
			if err != nil {
				if !started {
					transport.FailRequest(c, err)
				} else {
					transport.LogStreamError(ctx, err)
				}
			}
		}}
}
